export function getSeedFeaturedSites(size = 12): Site[] {
  return SEED_SITES.filter((s) => s.featured)
    .sort((a, b) => b.weight - a.weight)
    .slice(0, size);
}

export function getSeedLatestSites(size = 12): Site[] {
  return [...SEED_SITES]
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, size);
}

export function getSeedFeaturedCategories(): Category[] {
  return SEED_CATEGORIES.filter((c) => c.featured).sort(
    (a, b) => b.weight - a.weight,
  );
}

export function getSeedSiteByKey(siteKey: string): Site | undefined {
  return SEED_SITES.find((s) => s.siteKey === siteKey);
}


export function searchSeedSites({
  search,
  category,
  page,
  pricing = "all",
  rating = 0,
}: {
  search: string;
  category: string;
  page: number;
  pricing?: "all" | "free" | "paid";
  rating?: number;
}): { sites: Site[]; total: number } {
  const pageSize = 24;
  let filtered = SEED_SITES.filter((s) => s.state === SiteState.published);

  // Pricing filter
  if (pricing === "free") {
    filtered = filtered.filter((s) => s.pricingType?.includes("免费"));
  } else if (pricing === "paid") {
    filtered = filtered.filter((s) => !s.pricingType?.includes("免费"));
  }

  // Rating filter (skip for seed data as it doesn't have rating field)
  // TODO: Add rating field to seed data if needed

  if (category) {
    filtered = filtered.filter((s) =>
      s.categories.some((c) => c.includes(category)),
    );
  }

  if (search) {
    const q = search.toLowerCase();
    filtered = filtered.filter(
      (s) =>
        s.name.toLowerCase().includes(q) ||
        s.description.toLowerCase().includes(q) ||
        s.categories.some((c) => c.toLowerCase().includes(q)) ||
        s.searchSuggestWords.some((w) => w.toLowerCase().includes(q)),
    );
  }

  const total = filtered.length;
  const sites = filtered.slice((page - 1) * pageSize, page * pageSize);

  return { sites, total };
}

/**
 * 获取热门站点（按 voteCount 降序）
 */
export function getSeedTrendingSites(size = 12): Site[] {
  return SEED_SITES
    .sort((a, b) => (b.voteCount || 0) - (a.voteCount || 0))
    .slice(0, size);
}

/**
 * 获取站点统计数据（seed 降级用）
 */
export function getSeedSiteStats(): {
  totalSites: number;
  totalCategories: number;
  totalVotes: number;
  avgRating: string;
} {
  const totalSites = SEED_SITES.length;
  const catSet = new Set<string>();
  let totalVotes = 0;
  let ratingSum = 0;
  let ratingCount = 0;
  for (const s of SEED_SITES) {
    for (const c of s.categories) catSet.add(c);
    totalVotes += s.voteCount || 0;
    if (s.rating !== undefined) {
      ratingSum += s.rating;
      ratingCount++;
    }
  }
  const avgRating =
    ratingCount > 0 ? (ratingSum / ratingCount).toFixed(1) : "4.2";
  return { totalSites, totalCategories: catSet.size, totalVotes, avgRating };
}

/**
 * 根据分类获取相关站点（seed 降级用）
 */
export function getSeedRelatedByCategory(siteKey: string, size = 4): Site[] {
  const site = SEED_SITES.find((s) => s.siteKey === siteKey);
  if (!site) return [];
  return SEED_SITES.filter(
    (s) =>
      s.siteKey !== siteKey &&
      s.categories.some((c: string) => site.categories.includes(c))
  )
    .sort((a, b) => (b.voteCount || 0) - (a.voteCount || 0))
    .slice(0, size);
}
